-- Deezer artist ids for 11 pilot artists. Match rule: exact name on Deezer plus at least one release we already had from a sourced page.

-- Sandunes eras (sound lines researched for the board I design, each with its source).
select * from (values
 ('sandunes', 2012, 2018, 'Glitchy, mid-tempo post-dubstep, led by piano', array['Piano','Glitch beats','IDM','Downtempo','Garage'], 'https://rollingstoneindia.com/?p=41411', 'Rolling Stone India', 'night'),
 ('sandunes', 2019, 2022, 'Dreamy pop over hi-hat rhythms and airy synths', array['Airy synths','Hi-hats','Pop','Hip-hop'], 'https://ja.ra.co/reviews/24218', 'Resident Advisor', 'blush'),
 ('sandunes', 2023, null, 'Clarinet, strings and plucked bass', array['Clarinet','Strings','Plucked bass','Acoustic'], 'https://www.thewildcity.com/news/20319-sandunes-announces-new-album-with-single-the-surge-ft-ramya-pothuri', 'Wild City', 'ink')
) v(artist_slug, from_year, to_year, sound, tags, source_url, source_name, palette)
where not exists (select 1 from public.artist_eras e where e.artist_slug = 'sandunes');

